{
  "appName": "Fitness Tracker",
  "appType": "fitness tracking",
  "summary": "A fitness tracking app allowing users to log workouts and exercises, view their history, with premium members accessing advanced analytics and charts.",
  "entities": [
    {
      "name": "workout",
      "fields": ["userId", "date", "duration", "type", "exercises"]
    },
    {
      "name": "exercise",
      "fields": ["workoutId", "name", "sets", "reps", "weight"]
    }
  ],
  "roles": ["member", "premium member"],
  "features": ["workoutLogging", "historyView", "progressAnalytics", "charts"],
  "hasAuth": true,
  "hasPayments": true,
  "ambiguities": [],
  "assumptions": [
    "Users will have accounts to log in.",
    "Premium membership will be a subscription-based feature.",
    "Analytics and charts will be generated based on logged workout and exercise data."
  ],
  "clarifyingQuestions": []
}
